mapper.select:
SELECT id AS user_id,(is_enabled AND deleted_at IS NULL) AS enabled,auth_version,
    time_zone,pending_time_zone,time_zone_effective_at
FROM identity_user WHERE id=#{userId}

SELECT id,version,id AS goal_id,status,archived_at
FROM goal
WHERE id=#{id}
  AND user_id=#{userId}
  AND deleted_at IS NULL

SELECT id,version,week_start_date
FROM weekly_plan
WHERE id=#{id}
  AND user_id=#{userId}
  AND deleted_at IS NULL

SELECT count(*)
FROM stage
WHERE goal_id=#{id}
  AND user_id=#{userId}
  AND deleted_at IS NULL

SELECT count(*)
FROM task
WHERE stage_id=#{id}
  AND user_id=#{userId}
  AND deleted_at IS NULL

mapper.update:
UPDATE task_assignment
SET ended_at=clock_timestamp(),end_reason='TASK_DELETED',version=version+1,updated_at=clock_timestamp()
WHERE user_id=#{userId}
  AND task_id=#{id}
  AND ended_at IS NULL

UPDATE task_assignment a
SET ended_at=clock_timestamp(),end_reason='GOAL_ARCHIVED',version=a.version+1,updated_at=clock_timestamp()
FROM task t
JOIN stage s ON s.id=t.stage_id
  AND s.user_id=t.user_id
WHERE a.task_id=t.id
  AND a.user_id=#{userId}
  AND t.user_id=#{userId}
  AND s.goal_id=#{id}

  AND a.ended_at IS NULL
